      "proposed_laureates": [
        "Fabiola Gianotti",
        "Peter Jenni",
        "Tejinder Virdee"
      ],
      "assessment": {
        "nobel_worthiness": "The experimental discovery of the Higgs boson completed a central part of the Standard Model and confirmed a mechanism with deep consequences for particle physics.",
        "attribution": "Credit should recognize the leadership and construction of both ATLAS and CMS, whose independent results established the discovery; the named experimental leaders are plausible representatives.",
        "maturity": "The signal was independently observed in 2012 and its properties have since been studied extensively.",
        "uncertainties": [
          "The collaboration-wide nature of the work makes individual attribution difficult and any small laureate group necessarily incomplete."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B028",
      "proposed_laureates": [
        "Yakir Aharonov",
        "Michael V. Berry"
      ],
      "assessment": {
        "nobel_worthiness": "The Aharonov-Bohm effect and Berry phase show that quantum phases and gauge structure have observable consequences, shaping fundamental physics and many applications.",
        "attribution": "Aharonov's work established the effect's physical significance, while Berry identified the general geometric phase; the two contributions are distinct and complementary.",
        "maturity": "The effects have been repeatedly demonstrated and are now established concepts across quantum physics.",
        "uncertainties": [
          "The proposed pairing joins related but historically distinct contributions, and the award scope would need careful definition."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B004",
      "proposed_laureates": [
        "Eli Yablonovitch",
        "Philip St. J. Russell",
        "Sajeev John"
      ],
      "assessment": {
        "nobel_worthiness": "Photonic band gaps opened a powerful route to controlling light propagation and enabled important developments in photonics.",
        "attribution": "Yablonovitch and John independently established the photonic-crystal concept; Russell's photonic-crystal fibre work extended the idea into a transformative platform.",
        "maturity": "The foundational proposals and subsequent realizations have been validated across decades of experimental and technological work.",
        "uncertainties": [
          "The contribution of Susumu Noda and other builders of the field raises difficult boundary questions for a limited award."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B011",
      "proposed_laureates": [
        "Charles L. Kane",
        "Eugene J. Mele",
        "Laurens W. Molenkamp"
      ],
      "assessment": {
        "nobel_worthiness": "Topological insulators revealed new robust quantum phases and connected topological ideas to experimentally accessible electronic materials.",
        "attribution": "Kane and Mele developed the quantum spin Hall and topological-insulator theory; Molenkamp's experiments established the quantum spin Hall effect in a material.",
        "maturity": "The initial phase and edge-state phenomena have strong experimental support, though materials and manifestations continue to develop.",
        "uncertainties": [
          "The broader field includes several important experimental demonstrations beyond the proposed initial theory and quantum spin Hall experiment."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B014",
      "proposed_laureates": [
        "Francis Halzen",
        "Albrecht Karle",
        "Christian Spiering"
      ],
      "assessment": {
        "nobel_worthiness": "IceCube's observation of high-energy astrophysical neutrinos opened a new observational channel on the universe and established neutrino astronomy at extreme energies.",
        "attribution": "Halzen's scientific leadership and the sustained detector-building and organizational work of Karle and Spiering represent complementary parts of the achievement.",
        "maturity": "The astrophysical neutrino flux is well established, while source identification and population-level understanding remain active.",
        "uncertainties": [
          "The discovery depended on a large international collaboration, and the clearest source associations remain limited."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B058",
      "proposed_laureates": [
        "Charles L. Bennett",
        "David N. Spergel",
        "Lyman A. Page"
      ],
      "assessment": {
        "nobel_worthiness": "WMAP's precise full-sky microwave background measurements transformed cosmology into a quantitative discipline and tightly constrained the contents and history of the universe.",
        "attribution": "Bennett and Page represent key leadership in the mission and its measurements, while Spergel helped establish the cosmological interpretation of the results.",
        "maturity": "The measurements and their central cosmological conclusions have been extensively checked and reinforced by later observations.",
        "uncertainties": [
          "The distinction between the WMAP achievement and the broader sequence of CMB experiments requires a carefully bounded citation."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B005",
      "proposed_laureates": [
        "Maura McLaughlin",
        "Michael Kramer",
        "Xavier Siemens"
      ],
      "assessment": {
        "nobel_worthiness": "A nanohertz gravitational-wave background would reveal a major new regime of gravitational-wave astronomy and likely encode the history of massive black-hole binaries.",
        "attribution": "The named scientists represent important pulsar-timing and analysis contributions, but the evidence and instruments are products of multiple international collaborations.",
        "maturity": "Pulsar timing arrays have reported strong evidence for a common red process and a gravitational-wave interpretation, with accumulating evidence across datasets.",
        "uncertainties": [
          "The signal's astrophysical origin and detailed spectrum remain under study, and independent confirmation at the level expected for a discovery prize is still developing."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B013",
      "proposed_laureates": [
        "Alan H. Guth",
        "Andrei Linde",
        "Viatcheslav Mukhanov"
      ],
      "assessment": {
        "nobel_worthiness": "Inflation offers an influential account of early-universe dynamics, while quantum fluctuations provide a compelling mechanism for the origin of cosmic structure.",
        "attribution": "Guth and Linde made foundational contributions to inflationary cosmology; Mukhanov developed the quantitative connection between primordial fluctuations and observable structure.",
        "maturity": "The framework is consistent with major features of the observed universe, but the inflationary epoch itself and its distinctive primordial signatures have not been conclusively established.",
        "uncertainties": [
          "There is no unique inflationary model, and direct evidence such as primordial gravitational-wave signatures remains absent."
        ]
      }
    }
  ]
